  "No Razorpay account needed. ColonyHub collects through Razorpay Route and Razorpay transfers it to your society’s bank account.": "Razorpay ਖਾਤੇ ਦੀ ਲੋੜ ਨਹੀਂ। ColonyHub, Razorpay Route ਰਾਹੀਂ ਪੈਸਾ ਲੈਂਦਾ ਹੈ ਅਤੇ Razorpay ਉਸ ਨੂੰ ਤੁਹਾਡੀ ਸੋਸਾਇਟੀ ਦੇ ਬੈਂਕ ਖਾਤੇ ਵਿੱਚ ਭੇਜਦਾ ਹੈ।",
