  "Each device gets its own secret key. After you create it, give the key to your installer — they set the device to send it in the {header} header with every request.": "ਹਰ ਡਿਵਾਈਸ ਨੂੰ ਆਪਣੀ ਗੁਪਤ ਕੀ ਮਿਲਦੀ ਹੈ। ਬਣਾਉਣ ਤੋਂ ਬਾਅਦ ਇਹ ਕੀ ਆਪਣੇ ਇੰਸਟਾਲਰ ਨੂੰ ਦਿਓ — ਉਹ ਡਿਵਾਈਸ ਨੂੰ ਹਰ ਰਿਕਵੈਸਟ ਨਾਲ ਇਸ ਨੂੰ {header} ਹੈਡਰ ਵਿੱਚ ਭੇਜਣ ਲਈ ਸੈੱਟ ਕਰਨਗੇ।",
