  "Close {name}? Guards can no longer pick it. A gate with history is kept (closed) so old records still show it.": "{name} ਬੰਦ ਕਰਨਾ ਹੈ? ਗਾਰਡ ਇਸ ਨੂੰ ਹੁਣ ਨਹੀਂ ਚੁਣ ਸਕਣਗੇ। ਜਿਸ ਗੇਟ ਦਾ ਪੁਰਾਣਾ ਰਿਕਾਰਡ ਹੈ ਉਹ (ਬੰਦ ਰੂਪ ਵਿੱਚ) ਰੱਖਿਆ ਜਾਂਦਾ ਹੈ ਤਾਂ ਜੋ ਪੁਰਾਣੇ ਰਿਕਾਰਡਾਂ ਵਿੱਚ ਦਿਖਦਾ ਰਹੇ।",
