  "When a complaint misses its target time, these people are told — first straight away, then again if it is still open later. A rule for a specific category or priority wins over a general one.": "ਜਦੋਂ ਕੋਈ ਸ਼ਿਕਾਇਤ ਤੈਅ ਸਮੇਂ ਤੋਂ ਲੰਘ ਜਾਂਦੀ ਹੈ, ਤਾਂ ਇਨ੍ਹਾਂ ਲੋਕਾਂ ਨੂੰ ਦੱਸਿਆ ਜਾਂਦਾ ਹੈ — ਪਹਿਲਾਂ ਤੁਰੰਤ, ਫਿਰ ਬਾਅਦ ਵਿੱਚ ਵੀ ਖੁੱਲ੍ਹੀ ਰਹੇ ਤਾਂ ਦੁਬਾਰਾ। ਕਿਸੇ ਖ਼ਾਸ ਸ਼੍ਰੇਣੀ ਜਾਂ ਤਰਜੀਹ ਦਾ ਨਿਯਮ ਆਮ ਨਿਯਮ ਤੋਂ ਉੱਪਰ ਮੰਨਿਆ ਜਾਂਦਾ ਹੈ।",
