  "Society ads are switched off for this society by the ColonyHub platform team. Your ads are not shown and new ones can’t be created. Contact support to turn them back on.": "ColonyHub ਪਲੈਟਫਾਰਮ ਟੀਮ ਨੇ ਇਸ ਸੋਸਾਇਟੀ ਦੇ ਇਸ਼ਤਿਹਾਰ ਬੰਦ ਕਰ ਦਿੱਤੇ ਹਨ। ਤੁਹਾਡੇ ਇਸ਼ਤਿਹਾਰ ਨਹੀਂ ਦਿਖਦੇ ਅਤੇ ਨਵੇਂ ਨਹੀਂ ਬਣਾਏ ਜਾ ਸਕਦੇ। ਮੁੜ ਚਾਲੂ ਕਰਵਾਉਣ ਲਈ ਸਪੋਰਟ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
  "Top banners and pop-ups for your members — events, offers from local partners, reminders.": "ਤੁਹਾਡੇ ਮੈਂਬਰਾਂ ਲਈ ਉੱਪਰਲੇ ਬੈਨਰ ਅਤੇ ਪੌਪ-ਅੱਪ — ਸਮਾਗਮ, ਸਥਾਨਕ ਭਾਈਵਾਲਾਂ ਦੀਆਂ ਪੇਸ਼ਕਸ਼ਾਂ, ਰਿਮਾਈਂਡਰ।",
  "Log in as {name}": "{name} ਵਜੋਂ ਲੌਗ ਇਨ ਕਰੋ",
  "{who}. You will see the app exactly as they do. This is recorded and they can see it.": "{who}. ਤੁਹਾਨੂੰ ਐਪ ਬਿਲਕੁਲ ਉਵੇਂ ਦਿਖੇਗੀ ਜਿਵੇਂ ਉਹਨਾਂ ਨੂੰ ਦਿਖਦੀ ਹੈ। ਇਹ ਦਰਜ ਹੁੰਦਾ ਹੈ ਅਤੇ ਉਹ ਇਸਨੂੰ ਦੇਖ ਸਕਦੇ ਹਨ।",
  "Your password": "ਤੁਹਾਡਾ ਪਾਸਵਰਡ",
  "Two-step code": "ਦੋ-ਪੜਾਵੀ ਕੋਡ",
  "6-digit code from your app, or a backup code": "ਤੁਹਾਡੀ ਐਪ ਦਾ 6 ਅੰਕਾਂ ਦਾ ਕੋਡ, ਜਾਂ ਬੈਕਅੱਪ ਕੋਡ",
  "e.g. Checking the bill they reported": "ਜਿਵੇਂ: ਉਹਨਾਂ ਦੇ ਦੱਸੇ ਬਿੱਲ ਦੀ ਜਾਂਚ",
  "15 minutes": "15 ਮਿੰਟ",
