  "You can log in as: {roles}. Sessions last up to {hours} hours.": "ਤੁਸੀਂ ਇਹਨਾਂ ਵਜੋਂ ਲੌਗ ਇਨ ਕਰ ਸਕਦੇ ਹੋ: {roles}। ਸੈਸ਼ਨ ਵੱਧ ਤੋਂ ਵੱਧ {hours} ਘੰਟੇ ਚੱਲਦਾ ਹੈ।",
  "You cannot log in as other members.": "ਤੁਸੀਂ ਦੂਜੇ ਮੈਂਬਰਾਂ ਵਜੋਂ ਲੌਗ ਇਨ ਨਹੀਂ ਕਰ ਸਕਦੇ।",
  "See the app as a member sees it, to help them. The platform decides who may do this.": "ਮੈਂਬਰ ਦੀ ਮਦਦ ਲਈ ਐਪ ਨੂੰ ਉਵੇਂ ਦੇਖੋ ਜਿਵੇਂ ਉਹ ਦੇਖਦੇ ਹਨ। ਇਹ ਕੌਣ ਕਰ ਸਕਦਾ ਹੈ, ਪਲੈਟਫਾਰਮ ਤੈਅ ਕਰਦਾ ਹੈ।",
  "Who may log in as others here": "ਇੱਥੇ ਕੌਣ ਦੂਜਿਆਂ ਵਜੋਂ ਲੌਗ ਇਨ ਕਰ ਸਕਦਾ ਹੈ",
