  "Birthday and anniversary wishes: on/off, send time, channels and message text.": "ਜਨਮਦਿਨ ਅਤੇ ਵਰ੍ਹੇਗੰਢ ਦੀਆਂ ਸ਼ੁਭਕਾਮਨਾਵਾਂ: ਚਾਲੂ/ਬੰਦ, ਭੇਜਣ ਦਾ ਸਮਾਂ, ਮਾਧਿਅਮ ਅਤੇ ਸੁਨੇਹਾ।",
  "Open settings": "ਸੈਟਿੰਗਾਂ ਖੋਲ੍ਹੋ",
  "Added to every flat's bill each month, on top of the amounts above.": "ਉੱਪਰਲੀਆਂ ਰਕਮਾਂ ਤੋਂ ਇਲਾਵਾ ਹਰ ਮਹੀਨੇ ਹਰ ਫਲੈਟ ਦੇ ਬਿੱਲ ਵਿੱਚ ਜੁੜਦਾ ਹੈ।",
  "They'll be asked to set up an authenticator app the next time they open ColonyHub. Turn it on for yourself first from My profile.": "ਅਗਲੀ ਵਾਰ ColonyHub ਖੋਲ੍ਹਣ ’ਤੇ ਉਹਨਾਂ ਨੂੰ ਔਥੈਂਟੀਕੇਟਰ ਐਪ ਸੈੱਟ ਕਰਨ ਲਈ ਕਿਹਾ ਜਾਵੇਗਾ। ਪਹਿਲਾਂ ਮੇਰੀ ਪ੍ਰੋਫ਼ਾਈਲ ਤੋਂ ਇਸਨੂੰ ਆਪਣੇ ਲਈ ਚਾਲੂ ਕਰੋ।",
