  "Protect the accounts that can change money and member data.": "ਉਹਨਾਂ ਖਾਤਿਆਂ ਨੂੰ ਸੁਰੱਖਿਅਤ ਕਰੋ ਜੋ ਪੈਸੇ ਅਤੇ ਮੈਂਬਰ ਡਾਟਾ ਬਦਲ ਸਕਦੇ ਹਨ।",
