  "Bills, receipts, reminders, SOS alerts and wishes go out automatically. Each message uses one credit.": "ਬਿੱਲ, ਰਸੀਦਾਂ, ਰਿਮਾਈਂਡਰ, SOS ਅਲਰਟ ਅਤੇ ਸ਼ੁਭਕਾਮਨਾਵਾਂ ਆਪਣੇ-ਆਪ ਜਾਂਦੀਆਂ ਹਨ। ਹਰ ਸੁਨੇਹੇ ’ਤੇ ਇੱਕ ਕ੍ਰੈਡਿਟ ਲੱਗਦਾ ਹੈ।",
