  "Wishes": "ਸ਼ੁਭਕਾਮਨਾਵਾਂ",
  "Credits used up: automatic WhatsApp messages have stopped (SOS alerts still go out). In-app and push notifications continue.": "ਕ੍ਰੈਡਿਟ ਖ਼ਤਮ: ਆਪਣੇ-ਆਪ ਜਾਣ ਵਾਲੇ WhatsApp ਸੁਨੇਹੇ ਰੁਕ ਗਏ ਹਨ (SOS ਅਲਰਟ ਹਾਲੇ ਵੀ ਜਾਂਦੇ ਹਨ)। ਐਪ ਅਤੇ ਪੁਸ਼ ਸੂਚਨਾਵਾਂ ਜਾਰੀ ਰਹਿਣਗੀਆਂ।",
  "Running low — below {n} credits. Top up to keep messages going.": "ਕ੍ਰੈਡਿਟ ਘੱਟ — {n} ਤੋਂ ਹੇਠਾਂ। ਸੁਨੇਹੇ ਜਾਰੀ ਰੱਖਣ ਲਈ ਟੌਪ-ਅੱਪ ਕਰੋ।",
