  "Their name, email, phone and photo are removed, all sessions end and their memberships close. Bills, payments, receipts, registers and the audit log stay with the flat. This cannot be undone.": "ਉਹਨਾਂ ਦਾ ਨਾਮ, ਈਮੇਲ, ਫ਼ੋਨ ਅਤੇ ਫ਼ੋਟੋ ਹਟਾ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ, ਸਾਰੇ ਸੈਸ਼ਨ ਖ਼ਤਮ ਹੁੰਦੇ ਹਨ ਅਤੇ ਮੈਂਬਰਸ਼ਿਪ ਬੰਦ ਹੁੰਦੀ ਹੈ। ਬਿੱਲ, ਭੁਗਤਾਨ, ਰਸੀਦਾਂ, ਰਜਿਸਟਰ ਅਤੇ ਆਡਿਟ ਲੌਗ ਫਲੈਟ ਨਾਲ ਰਹਿੰਦੇ ਹਨ। ਇਸਨੂੰ ਵਾਪਸ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।",
  "The member is told why. Under the DPDP Act a request can be declined only for a lawful reason (for example, an open dispute or records you must keep).": "ਮੈਂਬਰ ਨੂੰ ਕਾਰਨ ਦੱਸਿਆ ਜਾਂਦਾ ਹੈ। DPDP ਐਕਟ ਅਧੀਨ ਬੇਨਤੀ ਸਿਰਫ਼ ਕਾਨੂੰਨੀ ਕਾਰਨ ਕਰਕੇ ਹੀ ਨਾਮਨਜ਼ੂਰ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ (ਜਿਵੇਂ ਕੋਈ ਖੁੱਲ੍ਹਾ ਝਗੜਾ ਜਾਂ ਉਹ ਰਿਕਾਰਡ ਜੋ ਰੱਖਣੇ ਲਾਜ਼ਮੀ ਹਨ)।",
